<template><view class="page"><view class="map"><RideMap v-if="trip" :markers="markers" :route-points="routePoints"/></view><RideStatusBar :title="statusText" :subtitle="trip?.order?.no||''"/><view v-if="trip" class="drawer"><view class="route"><text>起 · {{trip.originAddress}}</text><text>终 · {{trip.destinationAddress}}</text></view><view class="driver"><view><strong>{{trip.driverEmployee?.name||'正在匹配司机'}}</strong><text>{{trip.vehicle?.plateNumber||''}}</text></view><button v-if="trip.driverMemberId" size="mini" @tap="call">电话</button><button v-if="trip.driverMemberId" size="mini" @tap="chat=true">在线联系</button></view><view class="fare">预估 ¥{{money(trip.estimatedAmount)}}<text v-if="trip.finalAmount!=null">最终 ¥{{money(trip.finalAmount)}}</text></view><button v-if="trip.status==='PREPAY_PENDING'" class="primary" @tap="pay(trip.order.id)">立即支付</button><button v-if="trip.status==='SUPPLEMENT_PENDING'" class="primary" @tap="pay(trip.supplementOrderId)">支付补款</button><button v-if="['PREPAY_PENDING','DISPATCHING'].includes(trip.status)" class="cancel" @tap="cancel">取消行程</button></view><RideChatSheet v-if="trip" v-model="chat" :ride-id="trip.id" :member-id="memberId"/></view></template>
<script setup lang="ts">import{computed,onBeforeUnmount,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import RideMap from '../../../components/ride/RideMap.vue';import RideStatusBar from '../../../components/ride/RideStatusBar.vue';import RideChatSheet from '../../../components/ride/RideChatSheet.vue';import{rideApi}from'../../../services/ride';import{onRideRealtime}from'../../../services/ride-realtime';const trip=ref<any>(null),chat=ref(false);let id=0,stop:(()=>void)|null=null,poll:any;const memberId=computed(()=>Number(uni.getStorageSync('user')?.id||0));const routePoints=computed(()=>trip.value?.selectedRouteSnapshot?.points||[]);const markers=computed(()=>{if(!trip.value)return[];const t=trip.value,list:any[]=[{id:1,longitude:Number(t.originLongitude),latitude:Number(t.originLatitude),title:'起点'},{id:2,longitude:Number(t.destinationLongitude),latitude:Number(t.destinationLatitude),title:'终点'}],loc=t.locations?.[0];if(loc)list.push({id:3,longitude:Number(loc.longitude),latitude:Number(loc.latitude),title:'司机'});return list});const statusText=computed(()=>({PREPAY_PENDING:'等待预付',DISPATCHING:'等待司机接单',TO_PICKUP:'司机正在赶来',ARRIVED_PICKUP:'司机已到达',IN_TRIP:'行程进行中',ARRIVED_DESTINATION:'已到目的地',FARE_PENDING:'正在结算',SUPPLEMENT_PENDING:'等待补款',REFUND_PENDING:'退款处理中',COMPLETED:'行程已完成',CANCELLED:'行程已取消',NO_DRIVER:'暂无司机'}as any)[trip.value?.status]||'行程详情');async function load(){trip.value=await rideApi.detail(id)}async function pay(orderId:number){try{await rideApi.payOrder(orderId);uni.showToast({title:'支付成功',icon:'success'});setTimeout(load,800)}catch{uni.showToast({title:'支付未完成',icon:'none'})}}async function call(){const c=await rideApi.contact(id);uni.makePhoneCall({phoneNumber:c.phone})}async function cancel(){uni.showModal({title:'取消行程',content:'确认取消当前行程？',success:async r=>{if(r.confirm){await rideApi.cancel(id,'乘客取消');await load()}}})}function money(v:any){return Number(v||0).toFixed(2)}onLoad((q:any)=>{id=Number(q?.id||0);load();stop=onRideRealtime(()=>load());poll=setInterval(load,8000)});onBeforeUnmount(()=>{stop?.();clearInterval(poll)})</script>
<style scoped>.page{height:100vh;position:relative}.map{height:62vh}.drawer{position:absolute;left:20rpx;right:20rpx;bottom:24rpx;background:#fff;border-radius:30rpx;padding:24rpx;box-shadow:0 12rpx 40rpx rgba(15,23,42,.18)}.route{display:flex;flex-direction:column;gap:12rpx;padding-bottom:18rpx;border-bottom:1px solid #e2e8f0}.driver{display:flex;align-items:center;gap:10rpx;padding:18rpx 0}.driver>view{flex:1}.driver text{display:block;color:#64748b}.fare{display:flex;justify-content:space-between;font-weight:700}.primary{background:#0f172a;color:#fff;margin-top:16rpx}.cancel{margin-top:12rpx;color:#dc2626}</style>
